  born: string | null;
  wakes: number;
  last: string | null;
  mean_dur_s: number;
  interval: { declared: number | null; mean_gap_s: number | null };
  tools: Record<string, number>;
  generated_tokens: number;
  rests: number;
  diary_entries: number;
  files_changed_since_birth: string[];
  days: string[];
  exits: { t: string; code: number }[];
}

interface Message {
  type: string;
  text?: string;
  tool?: string;
  args?: unknown;
  status?: string;
}

interface Change {
  path: string;
  by?: string;
  author?: string;
  diff?: string;
  deleted?: boolean;
}

interface Beat {
  t: string;
  wake?: number;
  event?: string;
  code?: number;
  dur_s?: number;
  sleep_s?: number;
  rest?: boolean;
  error?: string;
  label?: string;
  messages?: Message[];
  changed?: Change[];
}

function own(beat: Beat): Change[] {
  return beat.changed?.filter((c) => c.by !== "outside") ?? [];
}

function outside(beat: Beat): Change[] {
  return beat.changed?.filter((c) => c.by === "outside") ?? [];
}

function fmtDur(s: number | null | undefined): string {
  if (s == null) return "–";
  if (s < 90) return `${Math.round(s)}s`;
  if (s < 5400) return `${Math.round(s / 60)}m`;
  return `${(s / 3600).toFixed(1)}h`;
}

